create extension if not exists pgcrypto;
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(trim(name)) between 1 and 120),description text not null default '',repository_full_name text not null default '',default_branch text not null default 'main',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists projects_user_updated_idx on public.projects(user_id,updated_at desc);
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('user','assistant')),content text not null check(char_length(trim(content)) between 1 and 50000),model text not null default '',created_at timestamptz not null default now());
create index if not exists messages_project_created_idx on public.messages(project_id,created_at asc);
create index if not exists messages_user_idx on public.messages(user_id);
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end; $$;
drop trigger if exists projects_set_updated_at on public.projects;
create trigger projects_set_updated_at before update on public.projects for each row execute function public.set_updated_at();
alter table public.projects enable row level security;
alter table public.messages enable row level security;
drop policy if exists "Users can read their own projects" on public.projects;
create policy "Users can read their own projects" on public.projects for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "Users can create their own projects" on public.projects;
create policy "Users can create their own projects" on public.projects for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists "Users can update their own projects" on public.projects;
create policy "Users can update their own projects" on public.projects for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "Users can delete their own projects" on public.projects;
create policy "Users can delete their own projects" on public.projects for delete to authenticated using((select auth.uid())=user_id);
drop policy if exists "Users can read messages in their projects" on public.messages;
create policy "Users can read messages in their projects" on public.messages for select to authenticated using((select auth.uid())=user_id and exists(select 1 from public.projects p where p.id=project_id and p.user_id=(select auth.uid())));
drop policy if exists "Users can add messages to their projects" on public.messages;
create policy "Users can add messages to their projects" on public.messages for insert to authenticated with check((select auth.uid())=user_id and exists(select 1 from public.projects p where p.id=project_id and p.user_id=(select auth.uid())));
drop policy if exists "Users can delete messages in their projects" on public.messages;
create policy "Users can delete messages in their projects" on public.messages for delete to authenticated using((select auth.uid())=user_id and exists(select 1 from public.projects p where p.id=project_id and p.user_id=(select auth.uid())));
grant select,insert,update,delete on public.projects to authenticated;
grant select,insert,delete on public.messages to authenticated;
